// Injects the metrics JSON into the dashboard template.
// "<" is escaped so a family name like "</script>" can never break out of the data block,
// and a replacer function is used so "$&" inside data is never interpreted by String.replace.
const TEMPLATE = "<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Admissions response report</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Readex+Pro:wght@300;400;500;600&display=swap" rel="stylesheet">
<style>
:root {
  --bg: #F3F5F1; --surface: #FFFFFF; --ink: #12241F; --muted: #5B6B65; --faint: #8C9A94; --rule: #DAE0DA;
  --accent: #0B6E4F; --meta: #5B4FD1; --web: #CF8605; --wa: #1E9E62; --late: #C4363D; --soft-late: #F6E3E3;
  --heat: 11, 110, 79;
  color-scheme: light;
  box-sizing: border-box;
  padding-top: env(safe-area-inset-top, 0px);
  padding-bottom: env(safe-area-inset-bottom, 0px);
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #0D1613; --surface: #14201C; --ink: #E6EEEA; --muted: #9AAAA4; --faint: #6F7F79; --rule: #26342F;
    --accent: #3FBF8F; --meta: #9C93FF; --web: #F2B13C; --wa: #45C98A; --late: #FF6B70; --soft-late: #3A1E20;
    --heat: 63, 191, 143; color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #0D1613; --surface: #14201C; --ink: #E6EEEA; --muted: #9AAAA4; --faint: #6F7F79; --rule: #26342F;
  --accent: #3FBF8F; --meta: #9C93FF; --web: #F2B13C; --wa: #45C98A; --late: #FF6B70; --soft-late: #3A1E20;
  --heat: 63, 191, 143; color-scheme: dark;
}
html { scroll-padding-top: env(safe-area-inset-top, 0px); }
*, *::before, *::after { box-sizing: inherit; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font-family: "Readex Pro", "Segoe UI", "Noto Sans Arabic", Tahoma, system-ui, sans-serif;
  font-weight: 300; font-size: 16px; line-height: 1.55;
  font-feature-settings: "tnum" 1; -webkit-font-smoothing: antialiased;
}
a { color: inherit; }
a:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 4px; }
.wrap { max-width: 1120px; margin: 0 auto; padding: 28px 22px 56px; }
.top { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 10px 24px; }
.school { font-weight: 500; }
.school span { color: var(--muted); font-weight: 300; }
.period { display: inline-flex; border: 1px solid var(--rule); border-radius: 999px; padding: 3px; background: var(--surface); }
.period a { text-decoration: none; padding: 4px 14px; border-radius: 999px; color: var(--muted); font-size: 14px; }
.period a[aria-current="true"] { background: var(--ink); color: var(--bg); }
.lede { font-size: clamp(26px, 3.6vw, 40px); line-height: 1.22; font-weight: 300; letter-spacing: -0.012em;
        max-width: 26ch; margin: 44px 0 14px; }
.sub { color: var(--muted); max-width: 70ch; margin: 0 0 30px; }
.demo { display: inline-block; font-size: 13px; color: var(--muted); border: 1px dashed var(--rule); padding: 2px 10px; border-radius: 999px; margin-top: 6px; }
section { padding: 30px 0 8px; border-top: 1px solid var(--rule); margin-top: 30px; }
