.note { color: var(--muted); font-size: 14px; margin: 0 0 16px; max-width: 72ch; }
svg { display: block; width: 100%; height: auto; max-width: 100%; overflow: visible; }
svg text { font-family: inherit; fill: var(--muted); font-size: 12px; }
.legend { display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 13px; color: var(--muted); margin: 10px 0 0; padding: 0; list-style: none; }
