.legend i.hollow { background: transparent !important; border: 2px solid var(--muted); width: 10px; height: 10px; }
.grid2 { display: grid; grid-template-columns: 1.15fr 0.85fr; gap: 26px 48px; }
@media (max-width: 820px) { .grid2 { grid-template-columns: 1fr; } }
.queue { list-style: none; margin: 0; padding: 0; }
.queue li { display: grid; grid-template-columns: 1fr auto; gap: 2px 16px; padding: 12px 0; border-bottom: 1px solid var(--rule); }
.queue li:last-child { border-bottom: 0; }
.queue .who { font-weight: 500; }
.queue .meta { color: var(--muted); font-size: 14px; grid-column: 1; }
.queue .age { text-align: right; font-weight: 500; white-space: nowrap; }
.queue .age small { display: block; font-weight: 300; color: var(--muted); font-size: 13px; }
.queue li.late .age { color: var(--late); }
.empty { color: var(--muted); padding: 14px 0; }
.dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; }
.scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
table { border-collapse: collapse; width: 100%; font-size: 14px; min-width: 520px; }
th { text-align: left; font-weight: 400; color: var(--muted); padding: 6px 12px 8px 0; border-bottom: 1px solid var(--rule); }
td { padding: 9px 12px 9px 0; border-bottom: 1px solid var(--rule); vertical-align: top; }
td.n, th.n { text-align: right; }
tr:last-child td { border-bottom: 0; }
td.bad { color: var(--late); }
.trend { display: flex; align-items: baseline; gap: 12px; margin: 0 0 6px; }
.trend b { font-size: 30px; font-weight: 400; }
.health { color: var(--muted); font-size: 14px; display: flex; flex-wrap: wrap; gap: 4px 22px; margin-top: 8px; }
.health .warn { color: var(--late); }
footer { margin-top: 40px; color: var(--faint); font-size: 13px; }
</style>
</head>
<body>
<main class="wrap" id="app" aria-live="polite"></main>
<script id="datasets" type="application/json">__DATASETS__</script>
<script>
(function () {
  'use strict';
  var DATASETS = JSON.parse(document.getElementById('datasets').textContent || '{}');
  var app = document.getElementById('app');
  var CH = {
    meta: { label: 'Facebook & Instagram forms', short: 'Meta form', color: 'var(--meta)' },
    web: { label: 'Website form', short: 'Website', color: 'var(--web)' },
    whatsapp: { label: 'WhatsApp (phase 2)', short: 'WhatsApp', color: 'var(--wa)' }
  };
  var DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function trim0(v) { return String(v).replace(/\.0$/, ''); }
  function fmtMin(m) {
    if (m == null || isNaN(m)) return 'n/a';
    m = Number(m);
    if (m < 1) return Math.max(1, Math.round(m * 60)) + ' s';
    if (m < 60) return (m < 10 ? trim0(m.toFixed(1)) : Math.round(m)) + ' min';
    var h = m / 60;
    if (h < 24) return (h < 10 ? trim0(h.toFixed(1)) : Math.round(h)) + ' h';
    return trim0((h / 24).toFixed(1)) + ' d';
  }
  function pct(v) { return v == null ? 'n/a' : Math.round(Number(v)) + '%'; }
  function num(v) { return Number(v || 0).toLocaleString('en-US'); }
  function rnd(i) { var t = Math.sin(i * 12.9898 + 78.233) * 43758.5453; return t - Math.floor(t); }
  function ago(iso) {
    if (!iso) return 'never';
    var m = (Date.now() - new Date(iso).getTime()) / 60000;
    return m < 1 ? 'just now' : fmtMin(m) + ' ago';
  }

  /* Hero: every inquiry placed by how long it took to be claimed (log scale) */
  function strip(d) {
    var W = 1000, H = 170, L = 6, R = 860, oL = 890, oR = 994, top = 26, bottom = H - 34;
    var lo = 0.5, hi = 2880;
    function x(m) {
      m = Math.max(lo, Math.min(hi, m));
      return L + (Math.log(m) - Math.log(lo)) / (Math.log(hi) - Math.log(lo)) * (R - L);
    }
    var ticks = [[1, '1 min'], [5, '5 min'], [15, '15 min'], [60, '1 h'], [240, '4 h'], [720, '12 h'], [1440, '1 day']];
    var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Time to first response for each inquiry">';
    ticks.forEach(function (t) {
      var tx = x(t[0]).toFixed(1);
      s += '<line x1="' + tx + '" x2="' + tx + '" y1="' + top + '" y2="' + bottom + '" stroke="var(--rule)"/>';
      s += '<text x="' + tx + '" y="' + (H - 12) + '" text-anchor="middle">' + t[1] + '</text>';
    });
    var sx = x(d.sla_reference_min || 15).toFixed(1);
    s += '<line x1="' + sx + '" x2="' + sx + '" y1="10" y2="' + bottom + '" stroke="var(--ink)" stroke-dasharray="3 4"/>';
    s += '<text x="' + (Number(sx) + 6) + '" y="18" style="fill:var(--ink)">' + esc(d.sla_reference_min) + '-minute promise</text>';
    s += '<rect x="' + oL + '" y="' + top + '" width="' + (oR - oL) + '" height="' + (bottom - top) + '" rx="6" fill="var(--soft-late)" opacity="0.55"/>';
    s += '<text x="' + ((oL + oR) / 2) + '" y="' + (H - 12) + '" text-anchor="middle">waiting</text>';
    (d.strip || []).forEach(function (p, i) {
      var claim = p[0], ch = CH[p[1]] || CH.web, after = p[3];
      var cx = claim == null ? oL + 10 + rnd(i + 7) * (oR - oL - 20) : x(claim);
      var cy = top + 6 + rnd(i) * (bottom - top - 12);
      s += after
        ? '<circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="3.2" fill="none" stroke="' + ch.color + '" stroke-width="1.4" opacity="0.8"/>'
        : '<circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="3.4" fill="' + ch.color + '" opacity="0.72"/>';
    });
    return s + '</svg>';
  }

  function bars(daily) {
    var W = 1000, H = 200, top = 12, bottom = H - 28, n = daily.length || 1, gap = n > 60 ? 1 : 2;
    var bw = W / n;
    var max = 1;
    daily.forEach(function (r) { max = Math.max(max, r.meta + r.web + r.whatsapp); });
    var step = max > 20 ? 10 : 5, nice = Math.ceil(max / step) * step;
    function y(v) { return bottom - v / nice * (bottom - top); }
    var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Inquiries per day by channel">';
    for (var g = 0; g <= nice; g += step) {
      s += '<line x1="0" x2="' + W + '" y1="' + y(g).toFixed(1) + '" y2="' + y(g).toFixed(1) + '" stroke="var(--rule)"/>';
      if (g) s += '<text x="' + (W - 2) + '" y="' + (y(g) - 4).toFixed(1) + '" text-anchor="end">' + g + '</text>';
    }
    var every = Math.ceil(n / 8);
    daily.forEach(function (r, i) {
      var x0 = i * bw + gap / 2, w = Math.max(1, bw - gap), acc = 0;
      ['meta', 'web', 'whatsapp'].forEach(function (k) {
        var v = r[k] || 0;
        if (!v) return;
        s += '<rect x="' + x0.toFixed(1) + '" y="' + y(acc + v).toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + (y(acc) - y(acc + v)).toFixed(1) + '" fill="' + CH[k].color + '"><title>' + esc(r.day) + ': ' + v + ' ' + esc(CH[k].short) + '</title></rect>';
        acc += v;
      });
      if (i % every === 0) {
        var dt = new Date(r.day + 'T12:00:00Z');
        s += '<text x="' + (x0 + w / 2).toFixed(1) + '" y="' + (H - 8) + '" text-anchor="middle">' + dt.getUTCDate() + ' ' + dt.toLocaleString('en-GB', { month: 'short', timeZone: 'UTC' }) + '</text>';
      }
    });
    return s + '</svg>';
  }

  function heat(cells, rules) {
    var cw = 38, chh = 24, lx = 44, ty = 8, W = lx + 24 * cw, H = ty + 7 * chh + 24, grid = {}, max = 1;
    cells.forEach(function (c) { grid[c[0] + '-' + c[1]] = c[2]; max = Math.max(max, c[2]); });
    var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Inquiries by weekday and hour">';
    for (var d = 1; d <= 7; d++) {
      s += '<text x="0" y="' + (ty + (d - 1) * chh + 16) + '">' + DAYS[d - 1] + '</text>';
      for (var h = 0; h < 24; h++) {
        var v = grid[d + '-' + h] || 0;
        s += '<rect x="' + (lx + h * cw + 1) + '" y="' + (ty + (d - 1) * chh + 1) + '" width="' + (cw - 2) + '" height="' + (chh - 2) + '" rx="3" fill="rgba(var(--heat),' + (v ? (0.12 + 0.88 * v / max).toFixed(2) : 0.05) + ')"><title>' + DAYS[d - 1] + ' ' + (h < 10 ? '0' : '') + h + ':00, ' + v + ' inquiries</title></rect>';
      }
    }
    (rules || []).forEach(function (r) {
      if (r.after_hours) return;
      var a = r.start.split(':'), b = r.end.split(':');
      var h0 = Number(a[0]) + Number(a[1]) / 60, h1 = Number(b[0]) + Number(b[1]) / 60;
      if (h1 <= h0) return;
      r.days.forEach(function (d) {
        s += '<rect x="' + (lx + h0 * cw).toFixed(1) + '" y="' + (ty + (d - 1) * chh + 0.5) + '" width="' + ((h1 - h0) * cw).toFixed(1) + '" height="' + (chh - 1) + '" fill="none" stroke="var(--ink)" stroke-opacity="0.35" stroke-width="1"/>';
      });
    });
    for (var t = 0; t < 24; t += 3) s += '<text x="' + (lx + t * cw + 2) + '" y="' + (H - 4) + '">' + (t < 10 ? '0' : '') + t + ':00</text>';
    return s + '</svg>';
  }

  function spark(weekly) {
    var W = 460, H = 130, pts = weekly.filter(function (w) { return w.median != null; });
    if (pts.length < 2) return '<p class="empty">Not enough history yet.</p>';
    var max = Math.max.apply(null, pts.map(function (p) { return p.median; }));
    function x(i) { return 8 + i / (pts.length - 1) * (W - 16); }
    function y(v) { return 10 + (1 - v / max) * (H - 36); }
    var path = pts.map(function (p, i) { return (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(p.median).toFixed(1); }).join(' ');
    var last = pts[pts.length - 1];
    var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Weekly median response time in staffed hours">';
    s += '<path d="' + path + '" fill="none" stroke="var(--accent)" stroke-width="2.2" stroke-linejoin="round"/>';
    s += '<circle cx="' + x(pts.length - 1).toFixed(1) + '" cy="' + y(last.median).toFixed(1) + '" r="4" fill="var(--accent)"/>';
    s += '<text x="8" y="' + (H - 6) + '">week of ' + esc(pts[0].week) + '</text>';
    s += '<text x="' + (W - 8) + '" y="' + (H - 6) + '" text-anchor="end">this week</text>';
    return s + '</svg>';
  }

  function render(d) {
    var k = (d.kpis && d.kpis.current) || {}, p = (d.kpis && d.kpis.previous) || {};
    var total = k.inquiries || 0, families = k.new_leads || 0;
    var h = '';
    h += '<header class="top"><div class="school">' + esc(d.school_name) + ' <span>admissions response report</span></div>';
    h += '<nav class="period" aria-label="Period">';
    [7, 30, 90].forEach(function (n) {
      h += '<a href="?days=' + n + '" data-days="' + n + '" aria-current="' + (n === d.days) + '">' + n + ' days</a>';
    });
    h += '</nav></header>';

    if (!total) {
      h += '<p class="lede">No inquiries in the last ' + d.days + ' days yet.</p>';
      h += '<p class="sub">Send a test lead (see tests/ in the project) and this page fills in within a minute.</p>';
    } else {
      h += '<p class="lede">' + num(total) + ' inquiries in the last ' + d.days + ' days, ' + num(families) + ' of them from new families. ' +
        'In staffed hours, half were picked up within ' + fmtMin(k.median_claim_staffed) + ', and ' + pct(k.sla_pct_staffed) + ' within the promised time.</p>';
      var subBits = [];
      if (k.after_hours_pct) subBits.push(pct(k.after_hours_pct) + ' arrived after hours and were picked up a median of ' + fmtMin(k.median_claim_after_hours) + ' later, at the start of the next shift.');
      if (p.inquiries) subBits.push('Previous ' + d.days + ' days: ' + num(p.inquiries) + ' inquiries, staffed-hours median ' + fmtMin(p.median_claim_staffed) + ', ' + pct(p.sla_pct_staffed) + ' on time.');
      if (k.merged) subBits.push(num(k.merged) + ' double submissions were merged instead of alerting the team twice.');
      h += '<p class="sub">' + esc(subBits.join(' ')) + '</p>';
    }
    if (d.has_demo) h += '<span class="demo">Includes generated demo history</span>';

    h += '<section aria-labelledby="s-strip"><h2 id="s-strip">Time to first response</h2>';
    h += '<p class="note">Each dot is one inquiry, placed by how long it took someone on the team to claim it. Hollow dots arrived after hours.</p>';
    h += strip(d);
    h += '<ul class="legend">' + ['meta', 'web'].map(function (c) { return '<li><i style="background:' + CH[c].color + '"></i>' + CH[c].label + '</li>'; }).join('') + '<li><i class="hollow"></i>after hours</li></ul></section>';

    h += '<section class="grid2"><div><h2>Waiting right now</h2>';
    var open = d.open || [];
    if (!open.length) {
      h += '<p class="empty">No one is waiting. Every inquiry has been picked up.</p>';
    } else {
      h += '<p class="note">' + open.length + ' ' + (open.length === 1 ? 'inquiry has' : 'inquiries have') + ' not been claimed yet. Reminders and escalations go out automatically.</p><ul class="queue">';
      open.slice(0, 8).forEach(function (o) {
        var tags = [CH[o.channel] ? CH[o.channel].short : o.channel];
        if (o.campaign) tags.push(o.campaign);
        if (o.agent) tags.push('with ' + o.agent);
        if (o.escalated) tags.push('escalated');
        else if (o.reminders) tags.push(o.reminders + (o.reminders === 1 ? ' reminder' : ' reminders'));
        h += '<li class="' + (o.overdue ? 'late' : '') + '"><span class="who" dir="auto">' + esc(o.name) + '</span>' +
          '<span class="age">' + fmtMin(o.minutes_open) + '<small>' + (o.after_hours && !o.overdue ? 'after hours' : (o.overdue ? 'past promise' : 'waiting')) + '</small></span>' +
          '<span class="meta">' + esc(tags.join(' · ')) + '</span></li>';
      });
      h += '</ul>';
    }
    h += '</div><div><h2>Getting faster</h2>';
    var wk = (d.weekly || []).filter(function (w) { return w.median != null; });
    if (wk.length > 1) {
      h += '<div class="trend"><b>' + fmtMin(wk[wk.length - 1].median) + '</b><span class="note" style="margin:0">median this week, staffed hours<br>from ' + fmtMin(wk[0].median) + ' in the first week shown</span></div>';
    }
    h += spark(d.weekly || []) + '</div></section>';

    var byCh = {};
    (d.channels || []).forEach(function (c) { byCh[c.channel] = c; });
    h += '<section><h2>Inquiries per day</h2><p class="note">';
    h += ['meta', 'web'].map(function (c) {
      var x = byCh[c] || {};
      return esc(CH[c].label) + ': ' + num(x.inquiries) + (x.median_claim_min != null ? ' (median response ' + fmtMin(x.median_claim_min) + ')' : '');
    }).join('. ') + '. WhatsApp joins in phase 2.</p>';
    h += bars(d.daily || []);
    h += '<ul class="legend">' + ['meta', 'web', 'whatsapp'].map(function (c) { return '<li><i style="background:' + CH[c].color + '"></i>' + CH[c].label + '</li>'; }).join('') + '</ul></section>';

    var cells = d.heatmap || [], outside = 0, all = 0;
    cells.forEach(function (c) { all += c[2]; });
    h += '<section><h2>When families write to us</h2><p class="note">Local time (' + esc(d.timezone) + '). Outlined blocks are staffed hours.' +
      (k.after_hours_pct ? ' ' + pct(k.after_hours_pct) + ' of inquiries land outside them.' : '') + '</p>';
    h += '<div class="scroll">' + heat(cells, d.rules) + '</div></section>';

    h += '<section class="grid2"><div><h2>Campaigns</h2><p class="note">Where inquiries came from, and how fast each source was answered.</p><div class="scroll"><table><thead><tr><th>Campaign</th><th class="n">Inquiries</th><th class="n">Arabic</th><th class="n">Median</th><th class="n">On time</th></tr></thead><tbody>';
    (d.campaigns || []).forEach(function (c) {
      h += '<tr><td><span class="dot" style="background:' + (CH[c.channel] || CH.web).color + '"></span>' + esc(c.campaign) + '</td><td class="n">' + num(c.inquiries) + '</td><td class="n">' + pct(c.arabic_pct) + '</td><td class="n">' + fmtMin(c.median_claim_min) + '</td><td class="n' + (c.sla_pct != null && c.sla_pct < 70 ? ' bad' : '') + '">' + pct(c.sla_pct) + '</td></tr>';
    });
    h += '</tbody></table></div></div><div><h2>Team</h2><p class="note">Claims are counted for whoever tapped claim first.</p><div class="scroll"><table><thead><tr><th>Name</th><th class="n">Assigned</th><th class="n">Median</th><th class="n">On time</th><th class="n">Open</th></tr></thead><tbody>';
    (d.agents || []).forEach(function (a) {
      h += '<tr><td>' + esc(a.agent) + '</td><td class="n">' + num(a.assigned) + '</td><td class="n">' + fmtMin(a.median_claim_min) + '</td><td class="n' + (a.sla_pct != null && a.sla_pct < 70 ? ' bad' : '') + '">' + pct(a.sla_pct) + '</td><td class="n">' + num(a.open) + '</td></tr>';
    });
    h += '</tbody></table></div></div></section>';

    var hl = d.health || {}, ib = hl.inbox || {}, le = hl.last_event || {};
    var stuck = (ib.failed || 0) + (ib.pending || 0) + (ib.processing || 0);
    h += '<section><h2>Pipeline health</h2><div class="health">';
